export const GUIDE_PLACES: Record<string, GuidePlace[]> = Object.fromEntries(
  Object.entries(RAW).map(([city, rows]) => [
    city,
    rows.map(([name, address, district, kinds, known, source]) => ({
      name,
      address,
      district,
      kinds: kinds.split(",") as PlaceKind[],
      known,
      source
    }))
  ])
);
